                new_k = k + 1
            elif piston == 2:
                if b is not None:
                    ejected[b] = ejected.get(b, Fraction(0)) + q
                new_a, new_b = c, (k if k <= 100 else None)
                new_c = (k + 1 if k + 1 <= 100 else None)
                new_k = k + 2
            else:
                if c is not None:
                    ejected[c] = ejected.get(c, Fraction(0)) + q
                new_a, new_b = b, (k if k <= 100 else None)
                new_c = (k + 1 if k + 1 <= 100 else None)
                new_k = k + 2
            ns = (new_a, new_b, new_c, new_k)
            nxt[ns] = nxt.get(ns, Fraction(0)) + q
